54	    async fn enroll(&self, node_id: &str, claim_code: Option<&str>) -> Response {
55	        if !self.limits.check(node_id, Bucket::Registration) {
56	            return Response::Throttled;
57	        }
58	
59	        if self.config.open_enrollment {
60	            return match db::enrollments::insert_enrollment(&self.db, node_id, None).await {
61	                // Idempotent whether or not a row was created: an open relay charges
62	                // nothing, so a repeat costs the caller nothing to report as success.
63	                Ok(_) => Response::Ok,
64	                Err(e) => internal(e, "failed to record enrollment"),
65	            };
66	        }
67	
68	        // Everything below runs inside one transaction, enrollment probe included. Reading
69	        // "already enrolled?" outside it would let two concurrent enrolls both see `false`,
70	        // and the one that lost the insert would have spent its grant code for nothing.
71	        let mut tx = match self.db.begin().await {
72	            Ok(tx) => tx,
73	            Err(e) => return internal(e, "failed to open enrollment transaction"),
74	        };
75	        match db::enrollments::is_enrolled(&mut *tx, node_id).await {
76	            // Idempotent: a node re-enrolling after a restart is not charged a code again.
77	            // Dropping `tx` unread rolls back, so nothing was consumed.
78	            Ok(true) => return Response::Ok,
79	            Ok(false) => {}
80	            Err(e) => return internal(e, "failed to check enrollment"),
81	        }
82	
83	        let Some(code) = claim_code else {
84	            // Same shape as a bad code: a caller cannot use the response to learn whether
85	            // this relay runs open enrollment beyond what its operator published.
86	            return Response::Denied;
87	        };
88	
89	        match db::enrollment_codes::consume_code(&mut *tx, code, node_id).await {
90	            Ok(true) => {}
91	            Ok(false) => return Response::Denied,
92	            Err(e) => return internal(e, "failed to redeem enrollment code"),
93	        }
94	        match db::enrollments::insert_enrollment(&mut *tx, node_id, Some(code)).await {
95	            Ok(true) => {}
