97	            // writer slipped in. Abandon the transaction (rollback), which un-redeems the
98	            // code, and report the enrollment that already stands.
99	            Ok(false) => return Response::Ok,
100	            Err(e) => return internal(e, "failed to record enrollment"),
101	        }
102	        match tx.commit().await {
103	            Ok(()) => {
104	                tracing::info!(%node_id, "node enrolled with a grant code");
105	                Response::Ok
106	            }
107	            Err(e) => internal(e, "failed to commit enrollment"),
108	        }
109	    }
