158	    async fn push(&self, node_id: &str, handle: &str) -> Response {
159	        match db::enrollments::is_enrolled(&self.db, node_id).await {
160	            Ok(true) => {}
161	            Ok(false) => {
162	                return Response::Pushed {
163	                    outcome: PushOutcome::NotEnrolled,
164	                }
165	            }
166	            Err(e) => return internal(e, "failed to check enrollment"),
167	        }
168	        if !self.limits.check(node_id, Bucket::Push) {
169	            return Response::Pushed {
170	                outcome: PushOutcome::Throttled,
171	            };
172	        }
173	
174	        match db::handles::resolve_handle(&self.db, node_id, handle).await {
175	            Ok(Some(_)) => Response::Pushed {
176	                // The APNs pipeline lands in the next phase; until then a well-formed push
177	                // to a real handle is honestly reported as an upstream failure rather than
178	                // as a delivery that never happened.
179	                outcome: PushOutcome::ApnsError,
180	            },
181	            Ok(None) => Response::Pushed {
182	                outcome: PushOutcome::UnknownHandle,
183	            },
184	            Err(e) => internal(e, "failed to resolve handle"),
185	        }
186	    }
