37	enum Command {
38	    /// Mint an enrollment grant code and print it. Hand the code to the instance
39	    /// operator; it is single-use and expires.
40	    MintCode {
41	        /// How long the code stays redeemable, e.g. `60m`, `24h`, `7d`, `900s`.
42	        #[arg(long, default_value = "60m")]
43	        ttl: String,
44	    },
