47	/// Convert a config `database_url` (a plain path or a sqlx URL) into a sqlx URL.
48	fn to_sqlite_url(s: &str) -> String {
49	    if s.starts_with("sqlite:") {
50	        s.to_owned()
51	    } else if s.starts_with('/') {
52	        format!("sqlite://{s}")
53	    } else {
54	        format!("sqlite:{s}")
55	    }
56	}
57	
58	/// Parse a `<number><s|m|h|d>` duration into seconds (Functional Core). A bare number is
59	/// read as seconds.
60	fn parse_ttl(spec: &str) -> anyhow::Result<i64> {
61	    let spec = spec.trim();
62	    let (digits, multiplier) = match spec.chars().last() {
63	        Some('s') => (&spec[..spec.len() - 1], 1),
64	        Some('m') => (&spec[..spec.len() - 1], 60),
65	        Some('h') => (&spec[..spec.len() - 1], 3600),
66	        Some('d') => (&spec[..spec.len() - 1], 86_400),
67	        _ => (spec, 1),
68	    };
69	    let value: i64 = digits
70	        .parse()
71	        .with_context(|| format!("invalid --ttl {spec:?}: expected e.g. 60m, 24h, 7d, 900s"))?;
72	    if value <= 0 {
73	        anyhow::bail!("--ttl must be positive");
74	    }
75	    value
76	        .checked_mul(multiplier)
77	        .context("--ttl is implausibly large")
78	}
79	
80	/// A code an operator can read aloud: 120 bits of entropy as 24 base32 characters, in
81	/// four groups of six for transcription.
82	fn generate_enrollment_code() -> String {
83	    let mut bytes = [0u8; 15];
84	    rand_core::RngCore::fill_bytes(&mut rand_core::OsRng, &mut bytes);
85	    let encoded = data_encoding::BASE32_NOPAD.encode(&bytes);
86	    encoded
87	        .as_bytes()
88	        .chunks(6)
89	        .map(|chunk| String::from_utf8_lossy(chunk).into_owned())
90	        .collect::<Vec<_>>()
91	        .join("-")
92	}
