94	fn load_config(path: Option<PathBuf>) -> anyhow::Result<config::Config> {
95	    let env = config::collect_env().context("failed to collect environment variables")?;
96	    match path {
97	        // An explicitly named file must exist — a typo'd path silently falling back to
98	        // env-only config would run the relay under settings the operator never chose.
99	        Some(path) => config::load_with_env(&path, &env)
100	            .with_context(|| format!("failed to load config from {}", path.display())),
101	        None => {
102	            let default_path = PathBuf::from("notify-relay.toml");
103	            match config::load_with_env(&default_path, &env) {
104	                Ok(config) => Ok(config),
105	                Err(config::ConfigError::Io { .. }) => config::load_from_env_only(&env)
106	                    .context("failed to load config from environment variables"),
107	                Err(e) => Err(e).context("failed to load config from notify-relay.toml"),
108	            }
109	        }
110	    }
111	}
