140	async fn run_serve(config_path: Option<PathBuf>) -> anyhow::Result<()> {
141	    let config = Arc::new(load_config(config_path)?);
142	    let pool = open_store(&config).await?;
143	
144	    let secret = identity::load_or_create_secret_key(&config.secret_key_path)?;
145	    let endpoint = transport::bind(secret, config.ipv6).await?;
146	    let node_id = endpoint.id().to_string();
