/// Wrap a push outcome in its response. Every push answers `pushed` — the outcome carries
/// the whole story, so a push never returns one of the shared refusal shapes.
fn pushed(outcome: PushOutcome) -> Response {
    Response::Pushed { outcome }
}

/// Log a storage failure and answer with a shape that reveals nothing about it.

/// Record that Apple accepted a notification for this handle.
///
/// Scoped by node id like every other query here, so it cannot be used to probe for
/// another node's handles by observing a write. Called only on a successful delivery:
/// `last_push_at` is the operator's "is this registration still live?" signal, and
/// stamping it on a refusal would make a dead device look healthy.
pub async fn touch_last_push(
    db: &SqlitePool,
    node_id: &str,
    handle: &str,
) -> Result<(), sqlx::Error> {
    sqlx::query("UPDATE handles SET last_push_at = datetime('now') WHERE handle = ? AND node_id = ?")
        .bind(handle)
        .bind(node_id)
        .execute(db)
        .await?;
    Ok(())
}

